DAYS=['07-23','07-24','07-25','07-26','07-27','07-28','07-29','07-30']
def am_shop(d):
    g=dc=od=0
    for h in AM_UTC:
        if (d,h) in SH: a,b,c=SH[(d,h)]; g+=a; dc+=b; od+=c
    return g,dc,od
def am_meta(d):
    c=i=k=p=v=0
    for h in range(12):
        if (d,h) in MH: x=MH[(d,h)]; c+=x[0]; i+=x[1]; k+=x[2]; p+=x[3]; v+=x[4]
    return c,i,k,p,v
def full_shop(d):
    g=dc=od=0
    for (dd,h),x in SH.items():
        if dd==d: g+=x[0]; dc+=x[1]; od+=x[2]
    return g,dc,od

